class ParkingSystem:
    def __init__(self, big: int, medium: int, small: int):
        # slot indices: 0=big, 1=medium, 2=small
        self.slots = [big, medium, small]

    def addCar(self, carType: int) -> bool:
        idx = carType - 1
        if self.slots[idx] > 0:
            self.slots[idx] -= 1
            return True
        return False
